#include<bits/stdc++.h>
using namespace std;
#define int long long
const int inf=0x3f3f3f3f;
signed main() {
    ios::sync_with_stdio(0);
    cin.tie(0),cout.tie(0);
    auto solve = [&]() {
        int n;
        cin>>n;
        vector<vector<vector<int>>> dp(2,vector<vector<int>>(440,vector<int>(440,inf)));
        int flag=0;
        dp[(flag^1)&1][0][0] = 0;
        for(int i=0;i<n;i++){
            int a,b,c,d;
            cin>>a>>b>>c>>d;
            for(int i=0;i<=400;i++){
                for(int j=0;j<=400;j++){
                    dp[flag&1][i+a][j]=min(dp[flag&1][i+a][j],dp[(flag^1)&1][i][j]);
                    dp[flag&1][i][j+a]=min(dp[flag&1][i][j+a],dp[(flag^1)&1][i][j]);
                    dp[flag&1][i+b][j+b]=min(dp[flag&1][i+b][j+b],dp[(flag^1)&1][i][j]+b);
                    dp[flag&1][i+c][j]=min(dp[flag&1][i+c][j],dp[(flag^1)&1][i][j]+c);
                    dp[flag&1][i][j+c]=min(dp[flag&1][i][j+c],dp[(flag^1)&1][i][j]+c);
                    dp[flag&1][i+d][j+d]=min(dp[flag&1][i+d][j+d],dp[(flag^1)&1][i][j]+d);
                    dp[(flag^1)&1][i][j]=inf;
                }
            }
            flag=flag^1;
        }
        int ans=inf;
        for(int i=0;i<=400;i++){
            for(int j=0;j<=400;j++){
                ans=min(ans,max(max(i,j),dp[(flag^1)&1][i][j]));
            }
        }
        cout<<ans;
    };
    // int t;
    // for(cin>>t;t;t--)
    solve();
    return 0;
}

